from __future__ import annotations

import hashlib
from typing import Any

from user_store import UserStore


def register_user(payload: dict[str, Any], store: UserStore) -> dict[str, Any]:
    email = str(payload.get("email", "")).strip().lower()
    password = str(payload.get("password", ""))
    name = str(payload.get("name", "")).strip()

    if "@" not in email or "." not in email:
        return {"ok": False, "reason": "invalid_email"}
    if len(password) < 8:
        return {"ok": False, "reason": "weak_password"}
    if len(name) < 2:
        return {"ok": False, "reason": "invalid_name"}
    if store.exists(email):
        return {"ok": False, "reason": "already_exists"}

    # Bug: stores plaintext password instead of hash.
    store.save({"email": email, "password": password, "name": name})
    return {"ok": True, "reason": "registered", "email": email}


def login_user(payload: dict[str, Any], store: UserStore) -> dict[str, Any]:
    email = str(payload.get("email", "")).strip().lower()
    password = str(payload.get("password", ""))
    user = store.get(email)
    if user is None:
        return {"ok": False, "reason": "invalid_credentials"}

    hashed_input = hashlib.sha256(password.encode("utf-8")).hexdigest()
    if user["password"] != hashed_input:
        return {"ok": False, "reason": "invalid_credentials"}

    return {"ok": True, "reason": "authenticated", "email": email}


def register_and_login(payload: dict[str, Any], store: UserStore) -> dict[str, Any]:
    reg = register_user(payload, store)
    if not reg.get("ok"):
        return reg
    login = login_user({"email": payload.get("email", ""), "password": payload.get("password", "")}, store)
    return {"ok": login.get("ok", False), "reason": login.get("reason", "unknown")}


def is_password_hashed(value: str) -> bool:
    candidate = value.strip().lower()
    if len(candidate) != 64:
        return False
    return all(char in "0123456789abcdef" for char in candidate)


def build_user_view(email: str, store: UserStore) -> dict[str, Any]:
    user = store.get(email)
    if user is None:
        return {"found": False}
    return {
        "found": True,
        "email": user.get("email", ""),
        "name": user.get("name", ""),
        "password_hashed": is_password_hashed(str(user.get("password", ""))),
    }

