from __future__ import annotations

from typing import Any


class UserStore:
    def __init__(self) -> None:
        self._users: dict[str, dict[str, Any]] = {}

    def save(self, user: dict[str, Any]) -> None:
        email = str(user.get("email", "")).strip().lower()
        if not email:
            raise ValueError("email required")
        self._users[email] = {
            "email": email,
            "password": str(user.get("password", "")),
            "name": str(user.get("name", "")).strip(),
        }

    def get(self, email: str) -> dict[str, Any] | None:
        key = email.strip().lower()
        if not key:
            return None
        user = self._users.get(key)
        if user is None:
            return None
        return dict(user)

    def exists(self, email: str) -> bool:
        return self.get(email) is not None

    def count(self) -> int:
        return len(self._users)

    def clear(self) -> None:
        self._users.clear()

    def snapshot(self) -> dict[str, dict[str, Any]]:
        return {key: dict(value) for key, value in self._users.items()}

    def emails(self) -> list[str]:
        return sorted(self._users.keys())

    def remove(self, email: str) -> bool:
        key = email.strip().lower()
        if not key or key not in self._users:
            return False
        del self._users[key]
        return True

    def rename_user(self, email: str, new_name: str) -> bool:
        key = email.strip().lower()
        candidate = new_name.strip()
        if not key or not candidate:
            return False
        user = self._users.get(key)
        if user is None:
            return False
        user["name"] = candidate
        self._users[key] = user
        return True

    def password_lengths(self) -> dict[str, int]:
        return {email: len(str(user.get("password", ""))) for email, user in self._users.items()}

